  const k = +readLine();
  const l = +readLine();
  const m = +readLine();
  const n = +readLine();
  const d = +readLine();
  const arr = Array(d).fill(1);
  let count = 0;
  function isDivisible(num) {
    return num % k === 0 || num % l === 0 || num % m === 0 || num % n === 0;
  }
  for (let i = 0; i < d; i++) {
    if (arr[i] === 1 && isDivisible(i + 1)) {
      arr[i] = -1;
    }
  }
  for (let i = 0; i < d; i++) {
    if (arr[i] === -1) count++;
  }
  console.log(count);
}

const main = async () => {
    const arr = [];
