 function findg(n, m){
    if(n === m){
        return 0;
    } else if(m === 0){
        return 1;
    }
    m--;
    n--;
    let gcount  = 1;
    for(let i = 0; i < m; i++){
        if(n === 0 || n === 1){
            gcount--;
        } else if (n === 2) {
            n-=2;
        } else {
            gcount++;
            n-=2;
        }
    }
    return gcount;
 }

