const find = (tasks, reserved) => {
    let bad = tasks * 2;
    let good = 0;
    let perTask = 5;

    const sum = (tasksCount) => 
        (2 * perTask + perTask * (tasksCount - 1)) 
            / 2 
            * tasksCount 
            + reserved;

    while (bad - good > 1) {
        let middle = (good + bad) >> 1;

        if (sum(middle) <= 240) {
            good = middle;
        } else {
            bad = middle;
        }
    }

    console.log(Math.min(good, tasks));
};

