let globalStdin = '';
const {EOL} = require('os');
process.stdin.on('data', i => globalStdin += i);

process.stdin.on('end', async () => {
  const lines = globalStdin.split(EOL);
  let [n, k] = lines[0].split(' ').map((v) => parseInt(v));
  let dp = Array.from({length: n+1}, () => new Array(n+1).fill(0));
  dp[0][0] = 1;
  let prev = {};
  for (let i = 1; i <= n; i++) {
    dp[i][0] = 1;
    let c = lines[1][i-1];
    for (let j = 1; j <= n; j++) {
      dp[i][j] = dp[i-1][j-1] + dp[i-1][j];
      if (prev[c]) dp[i][j] -= dp[prev[c] - 1][j - 1];
    }
    prev[c] = i;
  }
  let sum = 0;
  for (let i = n; i >= 0; i--) {
    if (dp[n][i] > k) {
      sum += (n - i) * k;
      k = 0;
      break;
    }
    k -= dp[n][i];
    sum += (n - i) * dp[n][i];
  } 
  console.log(k ? -1 : sum);
});

