function leastDifference(students, puzzles){
  puzzles = puzzles.sort((a, b) => a - b);

  let minDif = Infinity;

  let startIdx = 0;
  let endIdx = students - 1;

  while(endIdx < puzzles.length){
    let curDif = puzzles[endIdx] - puzzles[startIdx];
    minDif = Math.min(minDif, curDif); 
    startIdx ++;
    endIdx++;
  }
  console.log(minDif);
  return minDif;
}

