function solve(N) {
  const seen = new Set();
  let result = 1;
  let sqrtN = Math.floor(Math.sqrt(N));
  let a, b;
 
  for (let n = 2; n <= sqrtN; ++n) {
    a = n ** 2;
    b = n ** 3;
    
    if (a <= N && !seen.has(a)) {
      result++;
      seen.add(a);
    }
 
    if (b <= N && !seen.has(b)) {
      result++;
      seen.add(b);
    }
  }
 
  console.log(result);
}

