const distance = (a, b) => a > b ? a - b : b > a ? b - a : 0;

function solution(data) {
    const matrix = data.map(str => str.split(" ").map(Number));
    let a = 1, b = 1;
    for (let i = a; i <= matrix.length; i++) {
        for (let j = b; j <= matrix[0].length; j++) {
            if (matrix[(i-1)][(j-1)] === 1) {
                a = i;
                b = j;
                break;
            }
        }
        if (a !== 1 || b !== 1) break;
    };

	return distance(3, a) + distance(3, b);
};

