function comparison(n, m) {
  var firstStr = String(n);
  if(String(n).length == 1 || String(m).length == 1){
      return n == m ? console.log("OK") : console.log("WRONG_ANSWER")
  }    
  var result = '';
  var count = 0
  while( firstStr ) {
    var min = 999;
    for(var i = 0; i < firstStr.length; i++) {
      if(Number(firstStr[i] < min)) {
      	if(count == 0 && Number(firstStr[i]) == 0){ 
        } else {
        	min = firstStr[i]
        }
      }
  	}
    var index = firstStr.indexOf(min);
    result += firstStr.slice(index, index+1)
    firstStr = firstStr.slice(0, index) + firstStr.slice(index+1, firstStr.length)
    count ++
  } 
  if(result == m) {
  	console.log("OK")
  } else {
  	console.log("WRONG_ANSWER")
  }
}

function main() {
  const is = new Scanner();
  const word = `${is.nextLine()} `;
  let answer = true;
  for (let i = 0; i < word.length - 1; i += 1) {
    if (!isVowel(word[i]) && word[i] !== 'n') {
      if (!isVowel(word[i + 1])) {
        answer = false;
        break;
      }
    }
  }

  console.log(answer ? 'YES' : 'NO');

  function isVowel(n) {
    return n === 'a' || n === 'e' || n === 'i' || n === 'o' || n === 'u';
  }
}



