function gcd(a, b) {
  if ((a < 0) || (b < 0)) {
    throw Error('both inputs must be non-negative');
  } else if (a === 0) {
    if (b === 0) {
      throw Error('both inputs cannot be zero');
    } else {
      return b;
    }
  } else if (b === 0) {
    return a;
  } else {
    let m = Math.min(a, b);
    for (let i = m; i > 0; i = i - 1) {
      const x = a % i;
      const y = b % i;
      if ((x === 0) && (y === 0)) {
        return i;
      }
    }
    throw Error('this should not happen');
  }
}

function solve(y, w) {
  const num_faces = 6;
  const n = num_faces - Math.max(y, w) + 1;
  const g = gcd(n, num_faces);
  const a = n / g;
  const b = num_faces / g;
  return `${a}/${b}`;
};

