function nameLookUp(str) {

    let n = +str.trim();
    let arr = [];
    let max = [1];
    if (n > 1) {
        for (let index1 = 0; index1 < n; index1++) {
            arr[index1] = [];
            for (let index2 = 0; index2 < n; index2++) {

                if (index1 == 0 || index2 == 0) {
                    arr[index1][index2] = 1;

                }
                else {
                    let indexItem = arr[index1 - 1][index2] + arr[index1][index2 - 1];
                    max.push(indexItem);
                    arr[index1][index2] = indexItem;
                }


            }

        }
    }
    return Math.max(...max).toString();
}

