function nameLookUp(str) {
    let inputs = +str.trim();
    // if there is even number then make it half
    // if there is odd number then -(n+1)/2
    let fn = 0;
    if (inputs % 2 === 0) {
        fn = inputs / 2;
    }
    else {
        fn = -(inputs + 1) / 2;
    }
    return fn.toString();
}

