function snowball(weight, height, u1, d1, u2, d2) {
    let w = weight, h = height;
    for (; h >= 0; h--) {
        w += h;
        if (h == d1) w = (w - u1) > 0 ? (w - u1) : 0;
        if (h == d2) w = (w - u2) > 0 ? (w - u2) : 0;
    }
    return w;
}

