});

rl.on('close', function(cmd) {
    var n = parseInt(input[0]);
    var arr = input[1].split(' ').map(Number);

    var max = arrayMax(arr);
    var min = arrayMin(arr);

    var startIndex = 0;
    var endIndex = 0;

    var startCounting = false;

    for (var i = 0; i < n; i++) {
        if ((arr[i] == max || arr[i] == min) && !startCounting) {
            startCounting = true;
            startIndex = i;
            i++;
        }
        if ((arr[i] == max || arr[i] == min) && startCounting) {

            startCounting = false;
            endIndex = i;
            break;
        }
    }

    var maxarr = [];
    maxarr.push(endIndex - startIndex);
    maxarr.push(endIndex);
    maxarr.push(startIndex);
    maxarr.push(arr.length - 1 - startIndex);
    maxarr.push(arr.length - 1 - endIndex);

    function arrayMin(array) {
        var len = array.length,
            min = Infinity;
        while (len--) {
            if (array[len] < min) {
                min = array[len];
            }
        }
        return min;
    };

    function arrayMax(array) {
        var len = array.length,
            max = -Infinity;
        while (len--) {
            if (array[len] > max) {
                max = array[len];
            }
        }
        return max;
    };

    console.log(arrayMax(maxarr));
    process.exit(0);
});

