function nightAtMuseum(name) {
  let rotationCount = 0;
  let fixedPointer = "a";

  var alphabet = [
    "a",
    "b",
    "c",
    "d",
    "e",
    "f",
    "g",
    "h",
    "i",
    "j",
    "k",
    "l",
    "m",
    "n",
    "o",
    "p",
    "q",
    "r",
    "s",
    "t",
    "u",
    "v",
    "w",
    "x",
    "y",
    "z",
  ];

  for (let i = 0; i < name.length; i++) {
    let char = name[i];
    let pointerIndex = alphabet.indexOf(fixedPointer);
    let charIndex = alphabet.indexOf(char);

    rotationCount += Math.min(
      Math.abs(pointerIndex - charIndex),
      Math.min(pointerIndex, charIndex) -
        0 +
        (26 - Math.max(pointerIndex, charIndex))
    );

    fixedPointer = char;
  }
  console.log(rotationCount);

  return rotationCount;
}

