    if (word.length > 1)
        if (upperCase.test(word))
            return word.toLowerCase();
        else if (upperCase.test(word.slice(1)) && !upperCase.test(word.charAt(0)))
            return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
