function findElementLocation(keyboard, element) {
    for (let row = 0; row < 3; row++) {
        const cols = keyboard[row];
        for (let col = 0; col < 10; col++) {
            const colitem = cols[col];
            if (colitem == element) {
                return {
                    row: row,
                    col: col
                };
            }
        }
    }
    return {
        row: -1,
        col: -1
    };
}

