let store = [{}, {}, {}, {}, {}, {}, {}, {}, {}, {}];

function checkDigit(n, dig) {
  if (dig === 0 && n === 0) {
    return { count: 0, decrement: 0 };
  }
  return {
    count: 1,
    decrement: Math.max(n, dig) - n
  };
}

function splitNumber(n) {
  const digitsPow = 10 ** Math.floor(Math.log10(n));
  let first = Math.floor(n / digitsPow);
  let tail = n % digitsPow;
  return [first, tail];
}

function solveCore(n, dig = 0) {
  if (store[dig][n]) {
    return store[dig][n];
  }
  if (n < 10) {
    return (store[dig][n] = checkDigit(n, dig));
  }

  let rest = n;
  let [first, tail] = splitNumber(rest);
  let count = 0;

  while (rest > 0) {
    const r = solveCore(tail, Math.max(first, dig));
    count += r.count;
    rest -= tail + r.decrement;
    [first, tail] = splitNumber(rest);
  }

  return (store[dig][n] = { count, decrement: -rest });
