function ProblemSolver() {
    this.HAS_TEST_CASES = false;
    this.INPUT_FILE_NAME = "test.in";
    this.OUTPUT_FILE_NAME = "out.txt";
    this.DO_OUTPUT_TO_FILE = false;
    this.CLEAR_ARRAY_PER_CASE = false;

    this.solveCase = function() {
        var res , i , j , fl , cn , temp , k , l , str1 , str2 ;
        res = 0 ;
        len = this.s.length ;
        lim = Math.floor( ( len + this.k ) / 2 ) ;
        for( l = 1 ; l <= lim ; l++ ) {
        	for( i = 0 ; i < len + this.k ; i++ ) {
        		str1 = '' ;
        		for( j = i ; j < i + l && j < len + this.k ; j++ ) {
        			if( j >= len ) {
        				str1 += 'a' ;
        			}
        			else {
        				str1 += this.s.charAt( j ) ;
        			}
        		}
        		if( str1.length == l ) {
        			str2 = '' ;
	        		for( j = i + l ; j < i + 2 * l && j < len + this.k ; j++ ) {
	        			if( j >= len ) {
	        				if( j - l < len ) {
	        					str2 += this.s.charAt( j - l ) ;
	        				}
	        				else {
	        					str2 += 'a' ;
	        				}
	        			}
	        			else {
	        				str2 += this.s.charAt( j ) ;
	        			}
	        		}
	        		if( str2.length == l && str1 == str2 ) {
	        			res = l * 2 ;
	        			break ;
	        		}
        		}
        	}
        }
        print( res );
    };

    this.init = function() {
        this.lim1 = 100010;
        this.lim2 = 110;
        this.cc = 1;
        this.ind = 1;
        this.n = 0;
        this.cn = 0;
        this.declareAndFillArrays();
    };

    this.getInput = function( irObj ) {
        var hasMoreInput , i;
        hasMoreInput = true;
        try {
            this.s = irObj.nextString();
            this.k = irObj.nextInt();
        }
        catch( ex ) {
            hasMoreInput = false;
        }
        return hasMoreInput;
    };

    this.clearArraysPerCase = function() {
        var i;
        this.arr = new Array();
        this.adj_list = new Array();
        for( i = 0 ; i < this.lim1 ; i++ ) {
            this.arr.push( 0 );
            this.adj_list.push( new Array() );
        }
    };

    this.clearPerCase = function() {
        this.cn = 0;
        this.cc++;
        if( this.CLEAR_ARRAY_PER_CASE == true ) {
            this.clearArraysPerCase() ;
        }
    };

    this.declareAndFillArrays = function() {
        var i , j;
        this.srr = new Array();
