const solve = (n, m, a) => {
    if (n <= a) {
        if (m <= a) {
            return 1;
        } else {
            return 1 * Math.floor(m / a);
        }
    } else {
        if (m <= a) {
            return 1 * Math.floor(n / a);
        } else {
            let ms, ns;
            if (m % a != 0) {
                ms = Math.ceil(m / a);
            } else {
                ms = m / a;
            }
            if (n % a != 0) {
                ns = Math.ceil(n / a);
            } else {
                ns = n / a;
            }
            return ms * ns;
        }
    }
};

