function badges(b, g, n) {
  if (n === b + g) return 1;
  const min = Math.min(b, g);
  const sub = Math.max(b, g) < n ? n - Math.max(b, g) : 0;
  return min >= n ? 1 + n - sub : 1 + min - sub;
}

