function cutRibbon(ribbon, piecesLength) {
  let cuts = new Array(ribbon + 1).fill(0);
  cuts[0] = 0;
  piecesLength.forEach(ele => {
      cuts[ele] = 1;
  });

  for(let i = 1; i <= ribbon; i ++) {
    let cur = cuts[i]; 
    for(let piece of piecesLength){

    	if(piece <= i){
    	    if(cuts[i - piece] > 0){
                cur = Math.max(cur, 1 + cuts[i - piece]);	
    	    }
    	}
     }   

    cuts[i] = cur;
    }   
  return cuts[ribbon];

}

