function solve([n, m, k]) {
    if (n & 1) {
        const least = m / 2
        if (k < least) return false

        if (n === 1) return true
        const r = (k - least) % (n - 1)
    // console.log(n, m, k, r)
        return !(r & 1)
    } else {
        if (m & 1) {
            const side = n / 2
            return !(k & 1) && k <= (n * m / 2 - side)
        } else {
            return !(k & 1)
        }
    }
}

