// Return the charcter position
function charPosition(char) {
    let low = 0
    let high = chars.length - 1
    let mid = Math.floor((low + high) / 2)


    while (low <= high) {
        mid = Math.floor((low + high) / 2)
        if (chars.indexOf(char) > mid)
            low = mid + 1
        else if (chars.indexOf(char) < mid)
            high = mid - 1
        else
            return mid
    }

    return -1
}

