function minOperations(nums, k) {
  if (nums.length === 1) return 0;
  let totalMin = Number.MAX_VALUE;

  for (const num of nums) {
    let currNum = num;
    while (currNum > 0) {
      let arr = [];
      for (let i = 0; i < nums.length; i++) {
        let temp = nums[i];
        let operations = 0;
        while (temp > currNum) {
          temp = Math.floor(temp / 2);
          operations++;
        }
        if (temp === currNum) arr.push(operations);
      }
      if (arr.length < k) {
        currNum = Math.floor(currNum / 2);
        continue;
      } else {
        arr = arr.sort((a, b) => a - b);
        let minSum = 0;
        for (let j = 0; j < k; j++) {
          minSum += arr[j];
        }
        totalMin = Math.min(minSum, totalMin);
        currNum = Math.floor(currNum / 2);
      }
    }
  }

  if (totalMin === Number.MAX_VALUE) {
    return 0;
  }
  return totalMin;
}

