function findTheNumberOfLinesForLady(forTheNumberOfSquaress) {
    let a = Math.sqrt(forTheNumberOfSquaress);
    let b = Math.trunc(a);
    if (a == b) return 2 * a;
    if (b * (b + 1) >= forTheNumberOfSquaress) return 2 * b + 1;
    return 2 * b + 2;
}

