    const result = [];
    if (type === "upper") {
      for (let i = 0; i < word.length; i++) {
        const char = word[i];
        if (isLowerCase(char)) {
          let charCode = char.charCodeAt(0);
          result.push(String.fromCharCode(charCode - 32));
        } else {
          result.push(char);
        }
      }
    } else {
      for (let i = 0; i < word.length; i++) {
        const char = word[i];
        if (!isLowerCase(char)) {
          let charCode = char.charCodeAt(0);
          result.push(String.fromCharCode(charCode + 32));
        } else {
          result.push(char);
        }
      }
    }
    return result.join("");
  };
  for (let i = 0; i < word.length; i++) {
    if (isLowerCase(word[i])) lowerCount++;
    else upperCount++;
  }
