function solve(n) {
  marked = new Array(n+1,  false);
  count = 0;
  for(i = 1; i*i <= n; ++i) {    
    if(i*i*i <= n) {
      marked[i*i*i] = true;
      count++;
    }
    if(!marked[i*i]) {
      count++;
    }
  }
  return count;  
}

