function calc(next, acc) {
    if (next === 0)
        return acc;
    let unit1 = next%10;
    let rest1 = Math.floor(next/10);
    let ret1 = calc(rest1, unit1*acc);
    let ret2 = 0;
    if (unit1 < 9 && rest1>0) {
        let unit2 = 9;
        let rest2 = Math.floor(next/10) -1;

        ret2 = calc(rest2, unit2*acc);
    }
    return Math.max(ret1, ret2);
}

