function solve() {
   var k = BigInt(read());
   var str = 'codeforces';
   var n = str.length;

   var step = 0;
   var mul = 0n;

   while (mul <= k) {
      step++;
      mul = st(step, n);
   }

   step--;
   mul = st(step, n);
   var c = 0;

   while(mul < k) {
      c++;
      mul += mul / BigInt(step);
   }

   var ans = '';
   for (var i = 0; i < n; ++i) {
      ans += str[i].repeat(i < c ? step + 1 : step);
   }
   write(ans);
}

function st(n, k) {
   n = BigInt(n);
   var p = BigInt(1);
   for (var i = 0; i < k; ++i) {
      p *= n;
   }
   return p;
}


