const MOD = 1e9 + 7;
const mod = (n) => ((n % MOD) + MOD) % MOD;
const add = (a, b) => mod(mod(a) + mod(b));
function mul() {
  for (var a = arguments, r = a[0], i = a.length; --i; )
    r = ((((r >> 16) * a[i]) % MOD) * 65536 + (r & 65535) * a[i]) % MOD;
  return r;
}
function inv(b) {
  for (var a = MOD, u = 0, v = 1, t; b; v = t)
    (t = (a / b) | 0), (a -= t * b), (u -= t * v), (t = a), (a = b), (b = t), (t = u), (u = v);
  u %= MOD;
  return u < 0 ? u + MOD : u;
}

function main() {
  const n = +readLine();

  function countAlmostPrimes(n) {
    const primes = getAllPrimesUpto(n);
    let almostPrimeCount = 0;

    for (let i = 1; i <= n; i++) {
      let count = 0;
      let j = 0;
      while (primes[j] < i && j < n) {
        if (i % primes[j] === 0) count++;
        j++;
      }
      if (count === 2) almostPrimeCount++;
    }
    return almostPrimeCount;
  }

  console.log(countAlmostPrimes(n));
}

function getAllPrimesUpto(n) {
  const primes = [];
  for (let i = 2; i <= n; i++) {
    let isPrime = true;
    for (let j = 2; j <= Math.floor(Math.sqrt(i)); j++) {
      if (i % j === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) primes.push(i);
  }

  return primes;
}

