const solve = (equation) => {
    let res = '';
    let onesCounter = 0;
    let twosCounter = 0;
    let threesCounter = 0;

    for (let i = 0; i < equation.length; i++) {
        if (equation[i] === '1') onesCounter++;
        else if (equation[i] === '2') twosCounter++;
        else if (equation[i] === '3') threesCounter++;
    }

    while (onesCounter != 0) {
        res += '1+'
        onesCounter--;
    }

    while (twosCounter != 0) {
        res += '2+'
        twosCounter--;
    }

    while (threesCounter != 0) {
        res += '3+'
        threesCounter--;
    }

    if (res[res.length - 1] === '+') return res.slice(0, res.length - 1);
    else return res;
}

