const gcd = (a, b) => {
  if(b === 0) {
    return a;
  }

  return gcd(b, a % b);
}

rl.on('line', (d) => {
  const n = +d;
  let a, b;

  if (n % 2 === 1) {
    a = Math.floor(n / 2);
    b = Math.ceil(n / 2);
  }
  else {
    const mid = n / 2;
    a = mid - 1;
    b = mid + 1;
  }

  while (gcd(a, b) !== 1) {
    a--;
    b++;
  }

  console.log(a, b);
});

