const isPalindrome = (s) => {
  return s === [...s].reverse().join('');
}

const getLexicalLarger = (a, b) => {
  const arr = [a, b];
  const [r] = arr.sort().reverse();

  return r;
}

rl.on('line', (str) => {
  let best = '';
  const len = 2 ** str.length;

  for (let i = 0; i < len; i++) {
    const seq = i.toString(2).padStart(str.length, 0);
    let curr = '';

    for (let j = 0; j < seq.length; j++) {
      if (seq[j] === '1') {
        curr += str[j];
      }
    }

    if (isPalindrome(curr)) {
      best = getLexicalLarger(best, curr);
    }
  }

  console.log(best);
});

