function nameLookUp(str) {

    let inputs = +str.trim();
    let bills = [1, 5, 10, 20, 100];
    let billLength = bills.length;
    let moves = 0;
    while (inputs) {
        let diff = inputs - bills[billLength - 1];
        if (diff >= 0) {
            moves++;
            inputs = diff;
        }

        for (let index = billLength - 1; index >= 0; index--) {
            let diff = inputs - bills[index];
            if (diff >= 0) {
                inputs = diff;
                moves++;
                break;
            }

        }
    }

    return moves.toString();
}

