function removeAdjacent(l, s) {

	let sArr = Array.from(s);

	// create a dictionary where every letter in associated the its positions in the string, 
	// and a linkde list where every element has a reference in the dictionary near the position here stored

	let sll = {value:s[0], prev: null, next: null};
	let lettersDict = {[s[0]]: [{position: 0, elem: sll}]};
	let start = sll;
	let currElemLinkedList = sll;

	for (let i = 1; i < l; i++) {
		let curr = s[i];

		currElemLinkedList.next = {value:curr, prev: currElemLinkedList, next: null};
		if (curr in lettersDict) {
			lettersDict[curr].push({position: i, elem: currElemLinkedList.next});
		}
		else {
			lettersDict[curr] = [{position: i, elem: currElemLinkedList.next}];
		}

		currElemLinkedList = currElemLinkedList.next;
	}

	let end = currElemLinkedList;

	// order the keys of the dictionary by ascii value
	const keys = Object.keys(lettersDict);
	keys.sort((a, b) => {
		return b.charCodeAt(0) - a.charCodeAt(0)
	});

	// for every entry in keys check the string for adjacents
	return keys.reduce((acc, curr) => {
		let nEliminated = 0;


		for (let i = 0; i < lettersDict[curr].length; i++) {
			let elem = lettersDict[curr][i].elem;
			if (elem) {
				let position = lettersDict[curr][i].position;

				let leftComparable = elem.prev && elem.prev.value;
				let rightComparable = elem.next && elem.next.value;

				if ((leftComparable && (leftComparable.charCodeAt(0) - elem.value.charCodeAt(0) == -1)) ||
					(rightComparable && (rightComparable.charCodeAt(0) - elem.value.charCodeAt(0) == -1))) {
					nEliminated++;

					lettersDict[curr][i].elem = null;
					if (leftComparable === elem.value) {
						i -= 2
					}
					let prev = elem.prev;
					let next = elem.next;
					if (prev) {
						prev.next = next;
					}
					if (next) {
						next.prev = prev;
					}

				}

			}
		}

		return acc + nEliminated;
	}, 0)
}

