function minClicks(n, m) {
  let queue = [n];
  let distance = new Map();
  distance.set(n, 0);
  // BFS 
  while (queue[0] != m) {
    let cur = queue.shift();

    let curDist = distance.get(cur) + 1;
    if (!distance.get(cur - 1) && cur > 0 ) {
      distance.set(cur - 1, curDist);
      queue.push(cur - 1);
    }
    if (!distance.get(cur * 2) && cur < 10000) {
      distance.set(cur * 2, curDist);
      queue.push(cur * 2);
    }
  }
  console.log(distance.get(m));
}

