function solve(line) {
    const w = parseInt(line);
    let i = 1;
    while(Math.pow(2, i) <= Math.ceil(w / 2)) {
        const rem = w - Math.pow(2, i);
        if (rem % 2 === 0) return 'YES';
        i++;
    }
    return 'NO';
}

