    inputString = inputString.trim().split('\n').map(string => {
        return string.trim();
    });

    let lengthOfString = Number(inputString[0]);
    let string = inputString[1];

    solution(lengthOfString, string);

});

function solution(lengthOfString, string) {

    let onesCount = 0;
    let zeorCount = '';
    let digit = [];

    for (let index = 0; index < lengthOfString; index++) {

        if (string[index] == '1') {

            onesCount++;

            if (zeorCount.length > 1)
                digit.push(zeorCount.substring(0, zeorCount.length - 1));

            zeorCount = '';
        }

        if (string[index] == '0') {

            zeorCount += '0';

            if (onesCount)
                digit.push(onesCount.toString());

            onesCount = 0;
        }
    }

    if (onesCount)
        digit.push(onesCount.toString());

    if (zeorCount.length )
        digit.push(zeorCount);

    console.log(digit.join(""));

}

