function sol() {
  const A = input
    .split(' ')
    .map(Number);
  const sum = A.reduce((a, b) => a + b, 0);
  const result =
    (A[0] === sum - A[0]) ||
    (A[1] === sum - A[1]) ||
    (A[2] === sum - A[2]) ||
    (A[3] === sum - A[3]) ||
    (A[0] + A[1] === A[2] + A[3]) ||
    (A[0] + A[2] === A[1] + A[3]) ||
    (A[0] + A[3] === A[1] + A[2])

  process.stdout.write(
    result ? 'YES' : 'NO',
    'utf8',
    () => process.stdout.end()
  );
}

