const MODE = "SUBMIT";
const CF_1204_B = (n, l, r) =>  {
    /**
     * n, n-1, ..., n-l, 2^1, ..., 2^(l-1)
     * 2^1, ..., 2^(r-1), 2^(r-1), ..., 2^(r-1)
     * 
     * 5, 2, 3
     * => 1, 1, 1, 2
     * => 1, 2, 4, 4, 4 
     */
    const low_bound = 1 * (n - l + 1) + [...Array(l).keys()].slice(1).reduce((a, c) => a + Math.pow(2, c), 0);
    const high_bound = [...Array(r).keys()].reduce((a, c) => a + Math.pow(2, c), 0) + (n - r) * Math.pow(2, r - 1);
    return `${low_bound} ${high_bound}`;
}

