function enhance(hp) {
  const tuple = ['D', 0];
  for (let i = 0; i <= 2; i++) {
    const remainder = (hp + i) % 4;
    if (remainder === 1) {
      if ('A' < tuple[0]) {
        tuple[0] = 'A';
        tuple[1] = i;
      }
    }
    if (remainder === 3) {
      if ('B' < tuple[0]) {
        tuple[0] = 'B';
        tuple[1] = i;
      }
    }
    if (remainder === 2) {
      if ('C' < tuple[0]) {
        tuple[0] = 'C';
        tuple[1] = i;
      }
    }
  }
  return tuple;
}

function findGreeting( input ) {
  const greeting = 'hello';

  if ( input.length < greeting.length ) {
    return 'NO';
  }

  const inputArr = Array.from( input );
  let index = 0;

  for ( let i = 0; i < inputArr.length; i++ ) {
    const char = inputArr[ i ];

    if ( char === greeting[ index ] ) {
      index++;
    }
  }

  if ( greeting.length <= index ) {
    return 'YES';
  }

  return 'NO';
}



