function nameLookUp(str) {

    let inputs = str.trim().split('\n');
    let alphabets = inputs[1];
    let alphabetFound = [];
    for (let i = 65; i <= 90; i++) {
        let caps = String.fromCharCode(i);
        let small = caps.toLowerCase();
        let capIndex = alphabets.indexOf(caps);
        let smallIndex = alphabets.indexOf(small);
        if (capIndex !== -1 || smallIndex !== -1) {
            let index = capIndex !== -1 ? capIndex : smallIndex;
            alphabetFound.push(alphabets[index]);
        }
    }

    let msg = alphabetFound.length === 26 ? 'YES' : 'NO';

    return msg.toString();
}

