function fast_pow(a, p)
{
	let res = 1n;
	while (p) {
		if (p % 2n == 0) {
			a = a * a % MOD;
			p /= 2n;
		} else {
			res = res * a % MOD;
			p--;
		}
	}
	return res;
}

