let store = [{}, {}, {}, {}, {}, {}, {}, {}, {}, {}];

function checkDigit(n, dig) {
  if (dig == 0) {
    return { count: int(n == 0 ? 0 : 1), decrement: 0 };
  }
  if (dig > n) {
    return {
      count: int(1),
      decrement: dig - n
    };
  }
  return {
    count: int(2),
    decrement: dig
  };
}

function getNumString(arr) {
  const joined = arr.join("");
  const trimmed = joined.replace(/0/g, " ").trimLeft();
  return trimmed.replace(/\s/g, "0") || "0";
}

function solveCore(n, dig = 0) {
  if (store[dig][n]) {
    return store[dig][n];
  }
  if (n.length === 1) {
    return (store[dig][n] = checkDigit(n, dig));
  }

  let first = n[0];
  let tailArr = n.substring(1).split("");
  let total = int();

  while (first >= 0) {
    const r = solveCore(getNumString(tailArr), Math.max(first, dig));
    total = plus(total, r.count);
    first -= 1;
    tailArr = tailArr.map(() => "9");
    tailArr.pop();
    tailArr.push(`${(10 - r.decrement) % 10}`);
  }

  return (store[dig][n] = { count: total, decrement: 10 - tailArr.pop() });
}

function solve(n) {
  store = [{}, {}, {}, {}, {}, {}, {}, {}, {}, {}];
  const r = solveCore(n, 0);
  return bintToString(r.count);
}

