function formatString(str) {
  const arr = Array.from(str);

  return arr.reduce((acc, curr) => {
    curr = curr.toLowerCase();
    if (!vowels.includes(curr)) {
      acc.push('.', curr);
    }

    return acc;
  }, []).join('')
}

