function solve(n, k) {
    if (k.length >= n) return 0
    let has = 0
    for (let i = 0; i < k.length; i++) {
        if (+k[i] > 1) {
            has = 1
            break
        }
    }
    if (!has) return -1

    let q = {}
    q[k] = 1
    has = 1
    let count = 1
    const visited = {}
    while (has) {
        const nq = {}
        has = 0
        for (let s in q) {
            const bs = BigInt(s)
            for (let i = 0; i < s.length; i++) {
                const x = BigInt(s[i])
                const nx = bs * x
                if (visited[nx]) continue
                visited[nx] = 1
                // console.log(count, nx)
                if (String(nx).length >= n) return count
                nq[nx] = 1
                has = 1
            }
        }
        q = nq
        count++
    }
    return count
}

