function solve(n) {
    const dp = Array(n + 1).fill(0)
    for (let i = 1; i < n; i++) {
        for (let j = i + i; j <= n; j += i) {
            dp[j]++
        }
    }
    let sum = 1
    for (let i = 1; i <= n; i++) {
        dp[i] = add(dp[i], sum)
        sum = add(sum, dp[i])
    }
    return dp[n]
}

