let solution = function(x, arr) {
  let memo = {}
  let recur = function(n) {
    if (memo[n] != null) return memo[n]
    if (n < 0) return Number.MIN_SAFE_INTEGER
    if (n === 0) return 0
    let max = Number.MIN_SAFE_INTEGER
    for (let j of arr) {
      max = Math.max(max, 1 + recur(n - j))
    }
    memo[n] = max
    return max
  }
  return recur(x)
}
