function snowball(weight, height, u1, d1, u2, d2) {
    let w = weight, h = height;
    for (; h >= 0; h--) {
        w += h;
        if (h == d1) w = Math.max(w - u1, 0);
        if (h == d2) w = Math.max(w - u2, 0);
    }
    return w;
}

