function solve(input, target) {
  const D = [];
  for (let i = 0; i < target.length; i++) {
    D.push([]);
  }
  for (let i = 0; i < input.length; i++) {
    D[0][i] = input[i] === target[0] ? 1 : 0;
  }
  for (let j = 1; j < target.length; j++) {
    for (let i = 0; i < input.length; i++) {
      if (input[i] !== target[j]) {
        D[j][i] = 0;
        continue;
      }
      D[j][i] = D[j - 1].slice(0, i).reduce((acc, v) => acc + v, 0);
    }
  }
  return D.pop().reduce((acc, v) => acc + v);
}

