function calc(x)
{
    if (x==0) return 0;

    let str = x.toString();
    if (dp[str]) return dp[str];    
    let n = str.length;

    let v1 = abs(table[n+1]-x);
    let v2 = abs(table[n]-x);

    let ret;

    let diff = abs(v1-v2);
    let mx = max(v1,v2);
    let ratio = Number(diff * 100n / mx) / 100;
    if (ratio<=0.1)
    {
        ret = min(n+1+calc(v1),n+calc(v2));
    }
    else
    {
        if (v1<v2)
        {
            ret = n+1+calc(v1);        
        }
        else
        {
            ret = n+calc(v2);
        }
    }        

    dp[str] = ret;
    return ret;
}

