function solve(str){
  str = [...str]
  const subStr = [...'QAQ']
  const resultArr =  new Array(subStr.length).fill(0).map(() => new Array(str.length).fill(0));
  str.forEach((s, index) => {
    if(s === subStr[0]){
      resultArr[0][index] = 1
    } else {
      resultArr[0][index] = 0
    }
  })

  for (let i = 1; i < subStr.length; i ++){
    for (let j = 0; j < str.length; j ++){
      if(str[j] === subStr[i]){
        let sum = 0;
        for (let k = 0; k < j; k ++) {
          sum += resultArr[i-1][k]
        }
        resultArr[i][j] = sum;
      }
    }
  }
  let sum = 0;
  resultArr[subStr.length - 1].forEach(v => sum += v)
  return sum;
}

