function calArray(maxValue) {
    let set = new Set();
    let i = 1;
    while (maxValue >= i * i) {
        const square = i * i;
        const cube = i * i * i;
        set.add(square);
        if (cube <= maxValue) set.add(cube);
        i++;
    }
    return Array.from(set).sort((a, b) => a - b);
}

