//******************************MY FUNCTIONS */

function IsPrime(n)
{
    if (n == 2 ) return true;
    if (n <= 1|| n%2==0)
        return false;
        //for (int i = 2; i <= n/2; i++)
        //    if (n % i == 0)
        //        return false;
      var limit = parseInt(Math.sqrt(n));
    for (var i = 3; i <= limit; i+=2)                
        if (n % i == 0)
           return false;

    return true;    
}

function IsAlmostPrime(n, pNums)
{ 
    var countDivisor = 0;
    for (var i = 0; i < pNums.length; i++)
    {
        if (n % pNums[i] == 0) countDivisor++;
        if (pNums[i] > n / 2) break;
    }
    return countDivisor == 2;
}

