function solve(n) {
  let a = Math.floor(n / 2);
  let b = n - a;

  while (getGCD(a, b) != 1) {
    a--;
    b++;
  }

  return `${a} ${b}`;
}

function getGCD(a, b) {
  while (b != 0) {
    const tmp = a % b;
    a = b;
    b = tmp;
  }
  return a;
}

