function nameLookUp(arr) {
    let nMatrix = arr.split('+');
    for (let i = 1; i < nMatrix.length; i++) {
        let min = +nMatrix[i];
        let j = i - 1;
        while (j >= 0 && +nMatrix[j] > min) {
            nMatrix[j + 1] = +nMatrix[j];
            j--;
        }
        nMatrix[j + 1] = min;
    }
    return nMatrix.join('+').toString();

}

