function IO(rs, ws, readSize = 1024) {
  let buffer = Buffer.from([]);
  let nextLineIndex;
  let line;
  let chunk;

  return {
    rl() {
      while(true) {
        newLineIndex = buffer.indexOf('\n');

        if (newLineIndex === -1 && rs.readableLength === 0) {
          newLineIndex = buffer.length;
        }

        if (newLineIndex !== -1) {
          line = buffer.slice(0, newLineIndex);

          buffer = buffer.slice(newLineIndex + 1);

          return line.toString('utf-8');
        }

        if (rs.readableLength === 0) {
          return null
        }

        chunk = rs.read(Math.min(readSize, rs.readableLength));

        if (!chunk) { return null; }

        buffer = Buffer.concat([ buffer, chunk ]);
      }
    },

    wr(str) {
      return ws.write(str);
    },

    wl(str) {
      return ws.write(str + '\n');
    }
  };
}

