        var res , i , j , fl , cn , a , b , c , d ;
        res = 0 ;
        a = this.min1 ;
        b = this.min2 ;
        c = this.min3 ;
        d = this.n - ( a + b + c ) ;
        for( i = 1 ; i <= d ; i++ ) {
            if( a + 1 <= this.max1 ) {
                a++ ;
            }
            else if( b + 1 <= this.max2 ) {
                b++ ;
            }
            else if( c + 1 <= this.max3 ) {
                c++ ;
            }
        }
        print( a + ' ' + b + ' ' + c ) ;
    } ;

    this.init = function() {
        this.lim1 = 100010 ;
        this.lim2 = 110 ;
        this.cc = 1 ;
        this.ind = 1 ;
        this.n = 0 ;
        this.cn = 0 ;
        this.declareAndFillArrays() ;
    } ;

    this.getInput = function( irObj ) {
        var hasMoreInput , i ;
        hasMoreInput = true ;
        try {
        	this.n = irObj.nextInt() ;
        	this.min1 = irObj.nextInt() ;
        	this.max1 = irObj.nextInt() ;
        	this.min2 = irObj.nextInt() ;
        	this.max2 = irObj.nextInt() ;
        	this.min3 = irObj.nextInt() ;
        	this.max3 = irObj.nextInt() ;
        }
        catch( ex ) {
            hasMoreInput = false ;
        }
        return hasMoreInput ;
    } ;

    this.clearArraysPerCase = function() {
        var i ;
        this.arr = new Array() ;
        this.adjList = new Array() ;
        for( i = 0 ; i < this.lim1 ; i++ ) {
            this.arr.push( 0 ) ;
            this.adjList.push( new Array() ) ;
        }
    } ;

    this.clearPerCase = function() {
        this.cn = 0 ;
        this.cc++ ;
        if( this.CLEAR_ARRAY_PER_CASE == true ) {
            this.clearArraysPerCase() ;
        }
    } ;

    this.declareAndFillArrays = function() {
        var i , j ;
        this.srr = new Array() ;
        this.vis = new Array() ;
        this.arr = new Array() ;
        this.brr = new Array() ;
        this.memo = new Array() ;
        this.done = new Array() ;
        this.adjList = new Array() ;
        for( i = 0 ; i < this.lim1 ; i++ ) {
