    let inputs = str.trim().split('\n');
    let dragons = inputs.slice(0, inputs.length - 1);
    let totalDragons = +inputs[inputs.length - 1];
    let damagedDragons = [];

    for (let row of dragons) {
        for (let i = 1; i <= totalDragons; i++) {
            let multiple = row * i;
            if (multiple <= totalDragons) {
                damagedDragons.push(multiple);
            }
        }
    }
    damagedDragons = [...new Set(damagedDragons)].length;
    return damagedDragons.toString();
}

