function getMaxMin(n, l, r) {
  n = parseInt(n, 10);
  l = parseInt(l, 10);
  r = parseInt(r, 10);
  // get max
  let unique = 1;
  const arr = [];
  let curr = 1;
  while (unique < r && arr.length < n) {
    unique++;
    arr.push(curr);
    curr *= 2;
  }

  while (arr.length < n) {
    arr.push(curr);
  }

  const max = arr.reduce((a, b) => a + b);

  let index = arr.length - 1;

  // first pass
  while (index > 0 && arr[index] === curr) {
    arr[index] = 1;
    index--;
    if (arr[index] !== curr && unique === l) {
      arr[index + 1] = curr;
    }
  }

  unique--;

  while (index > 0 && unique > l && arr[index] !== 1) {
    arr[index] = 1;
    unique--;
    index--;
  }

  const min = arr.reduce((a, b) => a + b);
  console.log(`${min} ${max}`);
}

