function nameLookUp(str) {

    let inputs = str.trim().split(' ').map(num => Number(num));
    let minSocks = Math.min(...inputs);
    let maxSocks = Math.max(...inputs);
    let wearSameSocks = Math.floor((maxSocks - minSocks) / 2) > 0 ? Math.floor((maxSocks - minSocks) / 2) : 0;

    return minSocks + ' ' + wearSameSocks.toString();
}

