function rem(a, b) {
  if (b <= 0) {
    throw Error('divisor must be positive');
  } else {
    const r = (a % b);
    return (r < 0) ? (r + b) : r;
  }
}

function quot(a, b) {
  if (b <= 0) {
    throw Error('divisor must be positive');
  } else {
    const r = rem(a, b);
    const q = ((a - r) / b);
    return q;
  }
}

function ceil(a, b) {
  const r = rem(a, b);
  const q = quot(a, b);
  return (r === 0) ? q : (q + 1);
}

function solve(n, m, a) {
  const x = ceil(n, a);
  const y = ceil(m, a);
  const result = (x * y);
  return result;
}

