function solve(line) {
    const [a, b, c, d] = line.split(' ').map(v => parseInt(v));
    // console.log(a,b,c,d)
    if (isTriangle(a, b, c, d)) return 'TRIANGLE';
    if (isSegment(a, b, c, d)) return 'SEGMENT';
    return 'IMPOSSIBLE';
}

function isTriangle(a, b, c, d) {
    // abc, abd, bcd, acd
    if (a + b > c && a + c > b && b + c > a) return true;
    if (a + b > d && a + d > b && b + d > a) return true;
    if (c + b > d && c + d > b && b + d > c) return true;
    if (c + a > d && c + d > a && a + d > c) return true;
}

function isSegment(a, b, c, d) {
    if (a + b >= c && a + c >= b && b + c >= a) return true;
    if (a + b >= d && a + d >= b && b + d >= a) return true;
    if (c + b >= d && c + d >= b && b + d >= c) return true;
    if (c + a >= d && c + d >= a && a + d >= c) return true;
}

