function predict(test) {
    let op=''
    let ops=[]
    let opVariables = [];
    let limits = []
    for (let t of test) {
        // console.log(t);
        for(let i=0; i<t.length; i++) {
            if ( isOp(t[i]) ) {
                op = t[i]
                if ( isOp(t[i+1]) ) {
                    op += t[i+1]
                    i += 1
                }
                ops.push(op)
                op=''
            }
            else if (isChr(t[i])) {
                // console.log(t[i])
                op = t[i]
                for (var j = i + 1; j<t.length; j++) {
                    if (isChr(t[j]) || isInt(t[j])) {
                        op += t[j]
                        i = j
                    }
                    else
                        break
                }
                opVariables.push(op)
                op = ''
            } else {
                if ( i == 0 || (i>0 && isOp(t[i-1])) ) {
                    op = t[i]
                    let j = i + 1
                    for(; j<t.length; j++) {
                        if ( isInt(t[j]) ) {
                            op += t[j]
                            i = j
                        }
                        else
                            break
                    }
                    limits.push(op);
                    op = ''
                }
            }
        }
    }

    let min = limits[0]
    let max = limits[1]

    let pvs = ops.map((o,i) => [o, opVariables[i]])

    for(let pv of pvs) {
        if (pv[1] == undefined) {
            pv[1] = max
        }
        // print(`${min} ${pv[0]} ${pv[1]} ?`)
        if (eval(`${min}${pv[0]}${pv[1]}`)) {
            // print(` ${min} ${pv[0]} ${pv[1]} true`)
            min = pv[1]
        } else {
            print("input error");
            process.exit();
        }
    }
}

