const triangle = 'TRIANGLE';
const segment = 'SEGMENT';
const impossible = 'IMPOSSIBLE';

function triangle_segment_impossible(a, b, c) {
  if (a <= b) {
    if (b <= c) {
      const t = a + b;
      return (t > c) ? triangle : ((t === c) ? segment : impossible);
    }
  }
  throw Error('check failed: a <= b <= c');
};

function solve(a, b, c, d) {
  const e = triangle_segment_impossible(a, b, c);
  const f = triangle_segment_impossible(b, c, d);
  const g = triangle_segment_impossible(a, c, d);
  const h = triangle_segment_impossible(a, b, d);
  if ((e === triangle) ||
      (f === triangle) || 
      (g === triangle) ||
      (h === triangle)) {
    return triangle;
  } else if ((e === segment) ||
             (f === segment) ||
             (g === segment) ||
             (h === segment)) {
    return segment;
  } else {
    return impossible;
  }
};

