'use strict';

function solve(n, m) {
  const target = 10n ** (n - 1n);
  const queue = [[BigInt(m), 0]],
        cache = new Set();
  for (let [num, step] of queue) {
    const st = [];
    let tmp = num;
    while (num) {
      let cur = num % 10n;
      num = num / 10n;
      if (cur < 2n || st[cur]) continue;
      st[cur] = 1;
      let next = tmp * cur;
      if (cache.has(next)) continue;
      if (next >= target) {
        return step + 1;
      }
      cache.add(next);
      queue.push([next, step + 1]);
    }
  }
  return -1;
}

