function nameLookUp(str) {
    let inputs = str.trim();
    let upperCaseCount = inputs.replace(/[a-z]/g, '').length;
    let lowerCaseCount = inputs.replace(/[A-Z]/g, '').length;
    if (upperCaseCount == lowerCaseCount || lowerCaseCount > upperCaseCount) {
        inputs = inputs.toLowerCase();
    }
    else if (upperCaseCount > lowerCaseCount) {
        inputs = inputs.toUpperCase();
    }
    return inputs.toString();
}

