const main = inputArray => {
  const [
    numberOfParticipants,
    numberOfAdvancingScores,
  ] = inputArray[0].split(' ');
  const participantScores = inputArray[1].split(' ');
  const filter0s = score => score !== '0';
  if (numberOfAdvancingScores === numberOfParticipants)
    return participantScores.filter(filter0s).length;

  const winners = participantScores.slice(0, numberOfAdvancingScores);
  const lastWinningScore = winners[winners.length - 1];
  if (lastWinningScore === '0') return winners.filter(filter0s).length;

  if (participantScores[numberOfAdvancingScores] !== lastWinningScore)
    return winners.length;

  for (let i = winners.length; i < participantScores.length; i += 1) {
    if (participantScores[i] === lastWinningScore) {
      winners.push(lastWinningScore);
    } else {
      break;
    }
  }

  return winners.length;
};

