  //먼저 홀짝 쌍을 전부 세면서 동시에 cost도 셀 수 있나? 
  //그렇다면 각 cuttable point에 대해 세자! 
  var countingGroup = false;
  var balance = 0;
  var cutpoints = [];
  for (let i = 0; i < arr.length; i++) {
    const el = arr[i];
