      balance += 1;
    else
      balance -= 1;
    if(!countingGroup){
      //balance는 당연히 안맞을 것.
      it('counting started', i);
      countingGroup = true;
    }
    else if(countingGroup && balance == 0){
      if(i+1 == arr.length){
        break;
      }
      countingGroup = false;
      cutpoints.push({'pos': i+1, 'price': Math.abs(arr[i+1] - arr[i])});
      it('counting stopped', i);
    }
  }
  it(cutpoints);
  cutpoints.sort((x,y)=>{
    return x.price - y.price;
  });
  if(cutpoints.length == 0){
    print(0);
    return;
  }
  const prices = cutpoints.map((x)=>{return x.price;});
  it(prices);
