function solution(testCase) {
  const { n, m } = testCase;

  const modulo = 998244353n;

  let result = 0n;
  let toRemove = m;
  const primes = [];
  let primeProd = 1n;

  let exp = m;
  for (let l = 2n; l <= n; l++) {
    exp = (exp * m) % modulo;
    result = (result + exp) % modulo;
  }

  for (let l = 2n; l <= n; l++) {
    if (!primes.find((p) => l % p == 0)) {
      primes.push(l);
      primeProd *= l;
    }
    if (toRemove) {
      toRemove *= m / primeProd;
    }
    if (toRemove == 0) break;
    result = (result - toRemove) % modulo;
  }

  console.log(((result + modulo) % modulo).toString());
}

