function nameLookUp(str) {
    let frnLocation = str.trim();
    let moves = [1, 2, 3, 4, 5];
    let steps = [];
    for (let i = moves.length - 1; i >= 0; i--) {
        if (frnLocation % moves[i] === 0) {
            steps.push(Math.floor(frnLocation / moves[i]));
            break;
        } else {
            steps.push(Math.floor(frnLocation / moves[i]) + 1);
            break;
        }
    }
    return steps.toString();
}

