function parse(template, iLoop) {
    var out=[]
    var regex = /\d+/gm;
    var str = template;
    var m;
    var c = 0;
    while ((m = regex.exec(str)) !== null) {
        if (m.index === regex.lastIndex) {
            regex.lastIndex++;
        }
        if (c==iLoop) {break}
        out[c] = m[0];
        c+=1;
    }
    return out;
}

function result(n,k) {
    var min = n>k ? k : n;
    min = n>=k ? min - 1 : min;
    var start = k - n;
    start = start <= 0 ? 1 : start >= n ? n : start;
    return Math.floor((min - start + 1) / 2);
}

